written = set()

def write(lang, id, title, short, body, related):
    # Only touch files whose content changed, so a running dev server does not reload everything.
    os.makedirs(os.path.join(ROOT, lang), exist_ok=True)
    path = os.path.join(ROOT, lang, f"{id}.md")
    fill = lambda t: t.replace("{BUILDS}", PATCH_BUILDS).replace("{MIN}", MIN_PATCH)
    text = f"---\ntitle: {fill(title)}\nshort: {fill(short)}\nrelated: {related}\n---\n{fill(body)}\n"
    written.add(path)
    if os.path.exists(path) and open(path, encoding="utf-8").read() == text:
        return
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)

for id, (related, de, en) in TOPICS.items():
    write("de", id, *de, related)
    write("en", id, *en, related)
for id, (dt, ds, et, es) in ALARMS.items():
    write("de", id, dt, ds, "", "topic.alarms")
    write("en", id, et, es, "", "topic.alarms")
for id, (dt, ds, et, es) in PARAMS.items():
    write("de", id, dt, ds, "", "topic.params")
    write("en", id, et, es, "", "topic.params")
for id, (dt, ds, et, es) in SWITCHES.items():
    write("de", id, dt, ds, "", "topic.switches")
    write("en", id, et, es, "", "topic.switches")
# the English parameter titles are also the names in the app's parameter files (`app/src/params.ts` toExport): one
# source for what a parameter is called, keyed by its technical key
names_path = os.path.join(os.path.dirname(__file__), "..", "app", "src", "generated", "param_names.json")
